    /// `transitionMenu()` idiom; `validateLookAction` checks and dashes them.
    /// `LookMenuFiller` puts the project's LUTs before None when it opens.
    func lookMenu() -> NSMenu {
        let menu = NSMenu(title: "Look")
        menu.delegate = LookMenuFiller.shared
        for (index, kind) in LookKind.builtIns.enumerated() {
            menu.addItem(tagged(kind.displayName, #selector(EditorViewController.setLook(_:)), index))
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", #selector(EditorViewController.setLook(_:)), -1))
        return menu
    }

    /// Clip ▸ Camera Layout ▸ (road map "creator-jobs" CO6, spec §11 CO-66):
    /// Corner ▸, Rounded Corner ▸ and Circle ▸ with the four corners each, a
    /// separator, then Side by Side, Stacked, Camera Full and Screen Only —
    /// one selector, each row tagged with its index in
    /// `CameraLayoutChoice.menuRows`, the `transitionMenu()` idiom.
    func cameraLayoutMenu() -> NSMenu {
        let menu = NSMenu(title: "Camera Layout")
        let action = #selector(EditorViewController.switchCameraLayout(_:))
        let rows = CameraLayoutChoice.menuRows.enumerated()
        for shape in CameraLayoutShape.allCases {
            let corners = NSMenu(title: shape.menuTitle)
            for (index, row) in rows where row.kind == .corner && row.shape == shape {
                corners.addItem(tagged(row.title, action, index))
            }
            menu.addItem(submenuItem(corners))
        }
        menu.addItem(.separator())
        for (index, row) in rows where row.kind != .corner {
            menu.addItem(tagged(row.title, action, index))
        }
        return menu
    }

    /// Clip ▸ Switch Angle ▸ (road map "creator-jobs" SW1, spec §11 SW-15
    /// (a)): the placeholder until it opens, when `SwitchAngleMenuFiller`
    /// writes one row per covering track of the one selected clip. No key
    /// equivalent.
    func switchAngleMenu() -> NSMenu {
        let menu = NSMenu(title: "Switch Angle")
        menu.delegate = SwitchAngleMenuFiller.shared
        menu.addItem(SwitchAngleMenuFiller.placeholder())
        return menu
    }

    /// One slot's kinds, the `transitionMenu()` idiom: the index as the tag,
    /// a separator, None as −1.
    private func motionSlotMenu(_ title: String, _ names: [String], _ action: Selector) -> NSMenu {
        let menu = NSMenu(title: title)
        for (index, name) in names.enumerated() {
            menu.addItem(tagged(name, action, index))
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", action, -1))
        return menu
    }

    /// Built from `ClipLabel.allCases` with the case's index as the tag — the
    /// `transitionMenu()` idiom — so the six colours, their order and their
    /// inks come from the one file that owns them. Each item carries a dot in
    /// its colour: a label IS a colour, and a menu of six colour words that
    /// showed none would make the user picture them.
    func labelMenu() -> NSMenu {
        let menu = NSMenu(title: "Label")
        for (index, label) in ClipLabel.allCases.enumerated() {
            let entry = tagged(
                label.displayName, #selector(EditorViewController.setClipLabel(_:)), index)
            entry.image = Self.labelDot(label.color)
            menu.addItem(entry)
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", #selector(EditorViewController.setClipLabel(_:)), -1))
        return menu
    }

    /// A 10 pt filled circle — the timeline strip's 6 pt label dot at menu
    /// size. Not a template image: the point of it is its colour.
    private static func labelDot(_ color: NSColor) -> NSImage {
        let image = NSImage(size: NSSize(width: 10, height: 10), flipped: false) { rect in
            color.setFill()
            NSBezierPath(ovalIn: rect.insetBy(dx: 0.5, dy: 0.5)).fill()
            return true
        }
        return image
    }
}

/// Clip ▸ Look ▸'s LUT rows (spec §11 GR-8 [b]): between the eight's separator
/// and None, the project's `.cube` LUTs in media-list order, tag −2 with the
/// media id as `representedObject`, then a second separator — none of either
/// with no LUT. Rewritten each time the menu opens (`menuNeedsUpdate`), for
/// the main window's project; `UIMenu.fillDynamic` asks it for a named window.
final class LookMenuFiller: NSObject, NSMenuDelegate {
    static let shared = LookMenuFiller()

    func menuNeedsUpdate(_ menu: NSMenu) {
        fill(menu, for: NSApp.mainWindow)
    }

    func fill(_ menu: NSMenu, for window: NSWindow?) {
        let document = window?.windowController?.document as? ProjectDocument
        Self.fill(menu, luts: document.map { LookGallery.luts(in: $0.project.snapshot) } ?? [])
    }

    static func fill(_ menu: NSMenu, luts: [MediaSnapshot]) {
        guard let first = menu.items.firstIndex(where: \.isSeparatorItem) else { return }
        while menu.items.count > first + 2 { menu.removeItem(at: first + 1) }
        var at = first + 1
        for lut in luts {
            let item = NSMenuItem(
                title: LookGallery.lutName(lut),
                action: #selector(EditorViewController.setLook(_:)), keyEquivalent: "")
            item.tag = EditorViewController.lookLUTTag
            item.representedObject = NSNumber(value: lut.id)
            menu.insertItem(item, at: at)
            at += 1
        }
        if at > first + 1 { menu.insertItem(.separator(), at: at) }
    }
}

/// Clip ▸ Switch Angle ▸'s rows (spec §11 SW-15 (a)), rewritten each time the
/// menu opens for the main window's editor; `UIMenu.fillDynamic` asks it for
/// a named window. One row per `SwitchAngle.angles` of the ONE selected clip —
/// the track's title, its index as the tag, the track id as
/// `representedObject` — else the single `placeholder()`.
final class SwitchAngleMenuFiller: NSObject, NSMenuDelegate {
    static let shared = SwitchAngleMenuFiller()

    /// "No Covering Angle": `switchAngle(_:)` with no track, which its
    /// validator always turns off. It carries the action so the menu's
    /// selector is a live leaf before any project opens (the menu's
    /// three-way check, `v2_menu.py` H1).
    static func placeholder() -> NSMenuItem {
        NSMenuItem(
            title: "No Covering Angle",
            action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
    }

    func menuNeedsUpdate(_ menu: NSMenu) {
        fill(menu, for: NSApp.mainWindow)
    }

    func fill(_ menu: NSMenu, for window: NSWindow?) {
        let editor = window?.contentViewController as? EditorViewController
        var angles: [SwitchAngle.Angle] = []
        if let editor, let document = editor.document, editor.selectedClips.count == 1,
            let clip = editor.selectedClips.first
        {
            angles = SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
        }
        menu.removeAllItems()
        guard !angles.isEmpty else {
            menu.addItem(Self.placeholder())
            return
        }
        for (index, angle) in angles.enumerated() {
            let item = NSMenuItem(
                title: angle.title,
                action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
            item.tag = index
            item.representedObject = NSNumber(value: angle.track)
            menu.addItem(item)
        }
    }
}
