import AppKit

/// The export card's Speed row (codec-export C1, spec §11 CX-2, CX-12 (2)): "Speed:" under
/// Format (after Dynamic Range when an HLG project shows that), offering Faster, Balanced
/// and Smaller file — SVT-AV1's presets 8, 6 and 4 — Balanced the default. It is live only
/// on a row a bundled encoder writes (`ExportPreset.encoderSpeeds`, the `av1` row); on every
/// other row it is disabled and shows the last choice, as Quality does, and sends no
/// override. The choice is remembered with the rest of the card (`ExportChoice`).
extension ExportSheetController {
    /// The popup's items, each carrying its speed, and its wiring. Called from `loadView`
    /// before the remembered choice is applied.
    func configureSpeed() {
        for speed in EncoderSpeed.allCases {
            let item = NSMenuItem(title: speed.menuName, action: nil, keyEquivalent: "")
            item.representedObject = speed.rawValue
            speedPopup.menu?.addItem(item)
        }
        speedPopup.font = DS.sans(13)
        speedPopup.target = self
        speedPopup.action = #selector(speedChanged(_:))
        speedPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
        syncSpeed(Applies(currentPreset))
    }

    /// A pick: the choice, then a resolve, so the footnote follows the core's echo.
    @objc func speedChanged(_ sender: Any?) {
        guard let raw = speedPopup.selectedItem?.representedObject as? String,
            let speed = EncoderSpeed(rawValue: raw)
        else { return }
        encoderSpeedChoice = speed
        resolveCard()
    }

    /// The `encoder_speed` override: the choice on a row that takes one, nil elsewhere.
    func encoderSpeedOverride() -> String? {
import AppKit

/// The export card's Bit depth row (road map "audio" AP2 part 2, spec §11 AU-29): "Bit
/// depth:" after Quality, offering 16-bit and 24-bit — the master's rounding from the float
/// mix, never dithered — 16-bit the default. It is live only on a row that lists depths
/// (`ExportPreset.audioBits`, `audio_wav` and `audio_aiff`); on every other row it is
/// disabled and shows the last choice, as Speed does, and sends no override. The choice is
/// remembered with the rest of the card (`ExportChoice`).
extension ExportSheetController {
    /// The two depths the popup offers.
    static let audioBitDepths = [16, 24]

    /// The popup's items, each carrying its depth, and its wiring. Called from `loadView`
    /// before the remembered choice is applied.
    func configureAudioBits() {
        for bits in Self.audioBitDepths {
            let item = NSMenuItem(title: "\(bits)-bit", action: nil, keyEquivalent: "")
            item.representedObject = bits
            audioBitsPopup.menu?.addItem(item)
        }
        audioBitsPopup.font = DS.sans(13)
        audioBitsPopup.target = self
        audioBitsPopup.action = #selector(audioBitsChanged(_:))
        audioBitsPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
        syncAudioBits(Applies(currentPreset))
    }

    /// A pick: the choice, then a resolve, so the footnote follows the core's echo.
    @objc func audioBitsChanged(_ sender: Any?) {
        guard let bits = audioBitsPopup.selectedItem?.representedObject as? Int else { return }
        audioBitsChoice = bits
        resolveCard()
    }

    /// The `audio_bits` override: the choice on a row that takes one, nil elsewhere.
/// or stale layout reads `corner_square` (the owner's Corner, today's landing), and an absent
/// cutout reads off, tested by `object(forKey:) == nil`.
final class RecorderCameraLandingControls {
    let layoutPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let cutoutCheckbox = NSButton(
        checkboxWithTitle: "Remove the camera's background when it lands", target: nil,
        action: nil)

    init() {
        for layout in RecordingCameraLayout.allCases {
            let item = NSMenuItem(title: layout.title, action: nil, keyEquivalent: "")
            item.representedObject = layout.rawValue
            layoutPopup.menu?.addItem(item)
        }
        layoutPopup.toolTip = "Where the camera lands beside the screen recording."
        cutoutCheckbox.toolTip =
            "After the recording lands, run Clip ▸ Remove Background on the camera's clips as "
            + "its own undo step, \"Remove Background\"."
    }

    /// The pop-up's layout; `.cornerSquare` for no row.
    var layout: RecordingCameraLayout {
        let raw = layoutPopup.selectedItem?.representedObject as? String ?? ""
        return RecordingCameraLayout(rawValue: raw) ?? .cornerSquare
    }

    /// Selects `layout`'s row.
    func select(_ layout: RecordingCameraLayout) {
        if let item = layoutPopup.itemArray.first(where: {
            $0.representedObject as? String == layout.rawValue
        }) {
        for toggle in [systemAudioSwitch, showClicksSwitch] {
            toggle.target = self
            toggle.action = #selector(controlChanged(_:))
        }
        for box in [
            includeFrameJobCheckbox, cameraBesideCheckbox, enhanceMicrophoneCheckbox,
            recordShortcutsCheckbox, cameraLanding.cutoutCheckbox,
        ] + polishBoxes.all {
            box.font = DS.sans(13)
            box.target = self
            box.action = #selector(controlChanged(_:))
        }
        for rate in Self.rates {
            let item = NSMenuItem(title: "\(rate) fps", action: nil, keyEquivalent: "")
            item.tag = rate
            ratePopup.menu?.addItem(item)
        }
        // Cursor (spec §11 CU-36): read from `selectedItem`'s raw value, never by index.
        for cursor in RecordingCursor.allCases {
            let item = NSMenuItem(
                title: cursor == .separate ? "Separate" : "In the picture", action: nil,
                keyEquivalent: "")
            item.representedObject = cursor.rawValue
            cursorPopup.menu?.addItem(item)
        }
        for resolution in RecordingResolution.allCases {
            let item = NSMenuItem(
                title: resolution == .nominal ? "Nominal (points)" : "Best (pixels)",
                action: nil, keyEquivalent: "")
            item.representedObject = resolution.rawValue
            sizePopup.menu?.addItem(item)
        }
        // 120 pt exactly: the meter hugs at priority 1 and draws nothing under
        // 40, so without a width of its own the row would starve it.
        meterView.widthAnchor.constraint(equalToConstant: LevelMeterView.intrinsicWidth)
            .isActive = true
        meterView.setAccessibilityLabel("Microphone level")
        let microphoneRow = NSStackView(views: [microphonePopup, meterView])
        microphoneRow.orientation = .horizontal
        microphoneRow.alignment = .centerY
        microphoneRow.spacing = 8
    /// the current display.
    func rebuildSources() {
        let current = selectedDisplayID
        let voiceOver = voiceOverSelected
        let camera = cameraSelected
        let picked = pickedFilter != nil && sourcePopup.selectedItem?.tag == Self.windowTag
        sourcePopup.removeAllItems()
        for screen in NSScreen.screens {
            let item = NSMenuItem(title: screen.localizedName, action: nil, keyEquivalent: "")
            item.representedObject = NSNumber(value: Self.displayID(of: screen))
            sourcePopup.menu?.addItem(item)
        }
        sourcePopup.menu?.addItem(.separator())
        let window = NSMenuItem(
            title: picked ? "Window (picked)" : "Window…", action: nil, keyEquivalent: "")
        window.tag = Self.windowTag
        sourcePopup.menu?.addItem(window)
        let cameraRow = NSMenuItem(title: Self.cameraTitle, action: nil, keyEquivalent: "")
        cameraRow.tag = Self.cameraTag
        sourcePopup.menu?.addItem(cameraRow)
        let microphoneOnly = NSMenuItem(
            title: Self.microphoneOnlyTitle, action: nil, keyEquivalent: "")
        microphoneOnly.tag = Self.voiceOverTag
        sourcePopup.menu?.addItem(microphoneOnly)
        if voiceOver {
            sourcePopup.select(microphoneOnly)
        } else if camera {
            sourcePopup.select(cameraRow)
        } else if picked {
            sourcePopup.select(window)
        } else {
            selectDisplay(current)
        }
    }

    /// "Off", then every connected microphone (`connectedMicrophones()`, the
    /// session `ScreenRecorder.microphone(withID:)` asks, so a row here is a
    /// device the recorder can find), carrying its `uniqueID`.
    func rebuildMicrophones() {
        let current = microphonePopup.selectedItem?.representedObject as? String
        microphonePopup.removeAllItems()
        microphonePopup.menu?.addItem(NSMenuItem(title: "Off", action: nil, keyEquivalent: ""))
        for device in Self.connectedMicrophones() {
            let item = NSMenuItem(title: device.localizedName, action: nil, keyEquivalent: "")
            item.representedObject = device.uniqueID
            microphonePopup.menu?.addItem(item)
        }
        selectMicrophone(current)
    }

    /// "New Project" first, then every open document by `displayName` with
    /// its `recipeKey` in `representedObject`. The selection is the person's
    /// own choice while its document is still open, else the front document,
    /// else New Project.
    ///
    /// **Idle only** (R1 review). The rows used to follow the front document
    /// through a recording, so a person who pressed Record over "Untitled 2"
    /// and then clicked into "Untitled 3" to record it watched the row change
    /// to a document the recording was never going to land in — the choice
    /// was captured at the countdown's end. The guard is HERE rather than in
    /// the sync timer alone because the timer is not the only caller:
    /// `show()`, which the quit guard runs during a recording, rebuilds too.
    /// `landed()` sets the phase idle before its own rebuild, which is what
    /// moves the rows again.
    func rebuildDestinations() {
        guard phase == .idle else { return }
        let rows = Self.destinationRows()
        let listed = destinationPopup.itemArray.dropFirst().map { item in
            (item.title, (item.representedObject as? NSNumber)?.intValue ?? 0)
        }
        if destinationPopup.numberOfItems == 0 || !listed.elementsEqual(rows, by: { $0 == $1 }) {
            destinationPopup.removeAllItems()
            destinationPopup.menu?.addItem(
                NSMenuItem(title: "New Project", action: nil, keyEquivalent: ""))
            for (title, key) in rows {
                let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
                item.representedObject = NSNumber(value: key)
                destinationPopup.menu?.addItem(item)
            }
        }
        var wanted: Int?
        switch chosenDestination {
        case .some(.document(let key)) where rows.contains(where: { $0.1 == key }):
            wanted = key
        case .some(.newProject):
            wanted = nil
    /// Every connected camera by name, carrying its `uniqueID`, or the one
    /// row "None connected"; the selection kept when it is still listed,
    /// else the default (`selectCamera`).
    func rebuildCameras() {
        let current = selectedCameraID
        cameraPopup.removeAllItems()
        let cameras = CameraDevices.connected()
        for camera in cameras {
            let item = NSMenuItem(
                title: CameraDevices.popupTitle(CameraDevices.facts(of: camera)), action: nil,
                keyEquivalent: "")
            item.representedObject = camera.uniqueID
            cameraPopup.menu?.addItem(item)
        }
        if cameras.isEmpty {
            cameraPopup.menu?.addItem(
                NSMenuItem(title: Self.noCameraTitle, action: nil, keyEquivalent: ""))
        }
        selectCamera(current)
    }

    /// The row carrying `id`; nil, or an id no row carries, selects the
    /// default camera's row (CAM-3 (7): the system's preferred camera, else
    /// the first built-in, else the first), else the first row. The Format
    /// popup is rebuilt on every exit, the early one included (CAM-6 (2)).
    func selectCamera(_ id: String?) {
        defer { rebuildCameraFormats() }
        let rows = cameraPopup.itemArray
        if let id, let index = rows.firstIndex(where: { $0.representedObject as? String == id }) {
            cameraPopup.selectItem(at: index)
            return
        }
        let cameras = CameraDevices.connected().map(CameraDevices.facts(of:))
        let preferred = AVCaptureDevice.systemPreferredCamera?.uniqueID
        let wanted = CameraDevices.defaultIndex(in: cameras, preferredID: preferred).map {
            cameras[$0].uniqueID
        }
        let index =
            wanted.flatMap { wanted in
                rows.firstIndex { $0.representedObject as? String == wanted }
            } ?? 0
        if rows.indices.contains(index) { cameraPopup.selectItem(at: index) }
    }

    // MARK: - The Format popup (CAM-6)

    /// "Best (<the best format>)" — or "Best" when `camera` has none — then
    /// one row per `CameraDevices.formatRows` row, carrying its spelling;
    /// `stored` selected when a row carries it, else Best.
    func fillCameraFormats(_ camera: CameraDeviceFacts?, stored: String?) {
        formatPopup.removeAllItems()
        let formats = camera?.formats ?? []
        let best = camera.flatMap { CameraDevices.bestFormat($0.formats, active: $0.activeFormat) }
        let bestTitle =
            best.map { "\(Self.bestFormatTitle) (\(CameraDevices.formatTitle(formats[$0])))" }
            ?? Self.bestFormatTitle
        formatPopup.menu?.addItem(NSMenuItem(title: bestTitle, action: nil, keyEquivalent: ""))
        for index in CameraDevices.formatRows(formats) {
            let item = NSMenuItem(
                title: CameraDevices.formatTitle(formats[index]), action: nil, keyEquivalent: "")
