extension EditorViewController {

    @objc func splitAtShotChanges(_ sender: Any?) {
        guard let document, let window = view.window, window.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let targets = ShotSplit.targets(selectedClips.map(\.id), in: document.editedProject)
            .targets
        guard !targets.isEmpty else {
            NSSound.beep()
            return
        }
        let wants: [ShotSplit.Want]
        do {
            wants = try ShotSplit.wants(targets, in: document)
        } catch {
            refuseShotSplit(error.localizedDescription, document: document)
            return
        }
        guard !wants.isEmpty else {
            commitShotSplit(targets, document: document, grouped: false)
            return
        }
        let asked = document.project
        let scope = document.scope
        let rows = wants.map { AnalyzingSheetController.Row(name: $0.media.name, request: $0.request) }
        presentAsSheet(
            AnalyzingSheetController(
                document: document, command: ShotSplit.actionName, rows: rows
            ) { [weak self, weak document] outcome in
                guard let self, let document else { return }
                self.finishShotSplit(
                    outcome, targets: targets, asked: asked, scope: scope, document: document)
            })

AutoZoomSheetController : Zooms in where the recording's clicks and typing are, and back out after.  Each zoom is an ordinary action. One undo step.
FollowSubjectSheetController : Frames each selected clip on its subject with eased moves on its action lane,  and a blurred copy behind it where it shows the whole picture. Replaces the  clips' own position and scale. One undo step.
SpeedUpTypingSheetController : Plays the recording's typing faster where nobody speaks and no shortcut is  shown, keeping 0.3 s at normal speed at each end. One undo step.
VerticalVersionSheetController : Makes a version of the timeline for a tall or square canvas. Each full-frame  movie clip follows its subject with eased moves (with Speaker, whoever is  talking on the ticked microphones), stills and nests are  centred, and everything else is kept as placed, with a blurred copy behind a  clip where it shows the whole picture. With Make a copy it opens as a new  project and this one does not change. One undo step.
SwitchSpeakerSheetController : Cuts a Program track from the cameras, showing whoever talks on each  microphone. Run Synchronize Audio first. One undo step.
RetimeSheetController : Every unlocked track between In and Out plays faster or slower, and  everything after Out moves to stay in step. One undo step.
SpeedSheetController : Faster clips can leave gaps; slower clips can overlap. Later clips stay in  place. A clip an allowed overlap reaches gains a transition, named below.  If an overlap is not allowed, that clip stays unchanged; other selected  clips can still change.
SilenceSheetController : The quiet spans are cut and the timeline closes over them, as one edit.  Quiet is measured IN THE MIX, so a clip you have turned down, faded or  ducked never holds a cut up — and a span with nothing audible over it, a  gap or a muted clip alike, is left alone. Nothing INSIDE a nest is cut: a  nest plays from its first frame, so a cut into one would strand the rest  of it.
FillerSheetController : Each run of filler words — um, uh, er and the rest — is cut and the timeline  closes over it, as one edit. A cut is widened to the 32 ms speech grid so  the whole filler goes, but never into the words beside it, and its edges  snap inward to the frame grid. A filler that would cut into another clip's  word, a nest or a transition is left in.
AudioMatchSheetController : The other selected clips take the reference's loudness and its speech's  tone, written as their own Volume, Limiter and EQ settings in one undo  step. Each clip is measured as it plays, which takes a moment on a long  clip.
